-- El Grupo Parroquial lleva su año del 1 de enero al 31 de diciembre, no por
-- cursos: el programa de la página Cultos pasa a llamarse «Programa del año» y
-- sus cultos se ordenan de enero a diciembre (la Cuaresma primero).
--
-- El título se cambia siempre que siga siendo el de partida. El orden, solo si
-- las filas siguen tal cual se sembraron (hay dos órdenes de partida: el de la
-- migración cultos_en_programa y el del contenido por defecto): si alguien ya
-- las ha editado en el CMS, se quedan como están.
UPDATE `ContenidoPagina`
SET `datos` = REPLACE(`datos`, '"titulo":"Programa del curso"', '"titulo":"Programa del año"')
WHERE `slug` = 'cultos';

